// q99: vacates answered for a key at the places [0, 1, 2, 3, 4, 5], whether a row exists
// (<= (vacates ?f1 ?r1 ?f2 ?r2 ?f1 ?r1) (candidate ?c ?f1 ?r1 ?f2 ?r2))
fn q99c0(s: &St, d: &Dy, tm: &mut Terms, key: &[u32; 6]) -> bool {
    let b_f1 = key[0];
    let b_r1 = key[1];
    let b_f2 = key[2];
    let b_r2 = key[3];
    if key[4] != b_f1 { return false; }
    if key[5] != b_r1 { return false; }
    let key0: [u32; 5] = [FREE, b_f1, b_r1, b_f2, b_r2];
    let rows0: &[[u32; 5]] = d.r_candidate.get(2, &key0);
    for row0 in rows0.iter() {
        let v0 = row0[0];
        if row0[1] != b_f1 { continue; }
        if row0[2] != b_r1 { continue; }
        if row0[3] != b_f2 { continue; }
        if row0[4] != b_r2 { continue; }
        return true;
    }
    false
}
// (<= (vacates ?f1 ?r1 ?f2 ?r2 ?f3 ?r3) (en_passant ?c ?f1 ?r1 ?f2 ?r2) (ep_victim ?c ?f2 ?r2 ?f3 ?r3))
fn q99c1(s: &St, d: &Dy, tm: &mut Terms, key: &[u32; 6]) -> bool {
    let b_f1 = key[0];
    let b_r1 = key[1];
    let b_f2 = key[2];
    let b_r2 = key[3];
    let b_f3 = key[4];
    let b_r3 = key[5];
    let key0: [u32; 5] = [FREE, b_f1, b_r1, b_f2, b_r2];
    let rows0: &[[u32; 5]] = d.r_en_passant.get(0, &key0);
    for row0 in rows0.iter() {
        let v0 = row0[0];
        if row0[1] != b_f1 { continue; }
        if row0[2] != b_r1 { continue; }
        if row0[3] != b_f2 { continue; }
        if row0[4] != b_r2 { continue; }
        let key1: [u32; 5] = [v0, b_f2, b_r2, b_f3, b_r3];
        let rows1: &[[u32; 5]] = s.r_ep_victim.get(1, &key1);
        for row1 in rows1.iter() {
            if row1[0] != v0 { continue; }
            if row1[1] != b_f2 { continue; }
            if row1[2] != b_r2 { continue; }
            if row1[3] != b_f3 { continue; }
            if row1[4] != b_r3 { continue; }
            return true;
        }
    }
    false
}
// (<= (vacates e ?r ?kt ?r ?rf ?r) (castling_move ?c ?side e ?r ?kt ?r) (castling_path ?side ?kt ?rt ?rf))
fn q99c2(s: &St, d: &Dy, tm: &mut Terms, key: &[u32; 6]) -> bool {
    if key[0] != 108 { return false; }
    let b_r = key[1];
    let b_kt = key[2];
    if key[3] != b_r { return false; }
    let b_rf = key[4];
    if key[5] != b_r { return false; }
    let key0: [u32; 6] = [FREE, FREE, 108, b_r, b_kt, b_r];
    let rows0: &[[u32; 6]] = d.r_castling_move.get(3, &key0);
    for row0 in rows0.iter() {
        let v0 = row0[0];
        let v1 = row0[1];
        if row0[2] != 108 { continue; }
        if row0[3] != b_r { continue; }
        if row0[4] != b_kt { continue; }
        if row0[5] != b_r { continue; }
        let key1: [u32; 4] = [v1, b_kt, FREE, b_rf];
        let rows1: &[[u32; 4]] = s.r_castling_path.get(3, &key1);
        for row1 in rows1.iter() {
            if row1[0] != v1 { continue; }
            if row1[1] != b_kt { continue; }
            let v2 = row1[2];
            if row1[3] != b_rf { continue; }
            return true;
        }
    }
    false
}
fn q99(s: &St, d: &Dy, tm: &mut Terms, key: &[u32; 6]) -> bool { q99c0(s, d, tm, key) || q99c1(s, d, tm, key) || q99c2(s, d, tm, key) }
